<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { api, errorText } from '../api';
import type { AtlasCity, AtlasMap, AtlasGeometry } from '../../../packages/contracts/src/index.js';
import AtlasIcon from './AtlasIcon.vue';
const props = defineProps<{ scope: string; places: AtlasCity[]; selected: string | null }>();
const emit = defineEmits<{ region: [code: string]; place: [key: string] }>();
const data = ref<AtlasMap | null>(null), loading = ref(false), error = ref(''), zoom = ref(1), pan = ref([0, 0]); let dragged = false; let generation = 0, start: { x: number; y: number; pan: number[]; moved: boolean } | null = null;
function rings(geometry: AtlasGeometry['geometry']): number[][][] { const c = geometry.coordinates as any; return geometry.type === 'Polygon' || geometry.type === 'MultiLineString' ? c : geometry.type === 'MultiPolygon' ? c.flat() : geometry.type === 'LineString' ? [c] : []; }
const features = computed(() => data.value?.features ?? []);
const project = computed(() => {
  let bounds = [-180, -58, 180, 85]; const ratio = props.scope === 'world' ? 1 : .83;
  if (props.scope !== 'world' && features.value.length) { const points = features.value.flatMap(f => rings(f.geometry).flat()); bounds = [Infinity, Infinity, -Infinity, -Infinity]; for (const p of points) { bounds[0] = Math.min(bounds[0]!, p[0]!); bounds[1] = Math.min(bounds[1]!, p[1]!); bounds[2] = Math.max(bounds[2]!, p[0]!); bounds[3] = Math.max(bounds[3]!, p[1]!); } }
  const [x1, y1, x2, y2] = bounds as [number, number, number, number], scale = Math.min(740 / Math.max((x2 - x1) * ratio, .01), 420 / Math.max(y2 - y1, .01)) * zoom.value;
  return (p: number[]) => [(p[0]! - (x1 + x2) / 2) * ratio * scale + 400 + pan.value[0]!, ((y1 + y2) / 2 - p[1]!) * scale + 270 + pan.value[1]!];
});
const paths = computed(() => features.value.map(f => ({ ...f, path: rings(f.geometry).map(ring => ring.map((p, i) => { const xy = project.value(p); return `${i ? 'L' : 'M'}${xy[0]!.toFixed(2)},${xy[1]!.toFixed(2)}`; }).join('') + (f.geometry.type.includes('Polygon') ? 'Z' : '')).join('') })));
const pins = computed(() => {
  const list = props.places.filter(p => p.place.center && (props.scope === '100000' ? p.place.countryCode === 'CHN' : props.scope === 'world' ? false : p.place.provinceCode === props.scope || p.place.cityCode === props.scope)).map(p => ({ ...p, point: project.value(p.place.center!) }));
  return list.map(p => { const label = p.place.name.length > 8 ? p.place.name.slice(0, 8) + '…' : p.place.name, labelWidth = label.length * 22, left = p.point[0]! + labelWidth + 30 > 780 || list.some(other => other !== p && other.point[0]! > p.point[0]! && other.point[0]! - p.point[0]! < labelWidth + 40 && Math.abs(other.point[1]! - p.point[1]!) < 42); return { ...p, label, labelWidth, left }; });
});
function lit(code: string) { return props.places.some(p => p.records > 0 && (props.scope === 'world' ? p.place.countryCode === code : props.scope === '100000' ? p.place.provinceCode === code : p.place.cityCode === code || p.place.provinceCode === p.place.cityCode && p.place.provinceCode === props.scope)); }
function region(code: string, keyboard = false) { if ((!dragged || keyboard) && code) emit('region', code); }
function pick(key: string, keyboard = false) { if (!dragged || keyboard) emit('place', key); }
async function load() { const current = ++generation; loading.value = true; error.value = ''; data.value = null; zoom.value = 1; pan.value = [0, 0]; try { const value = await api<AtlasMap>('/atlas/maps/' + props.scope); if (current === generation) data.value = value; } catch (e) { if (current === generation) error.value = errorText(e); } finally { if (current === generation) loading.value = false; } }
watch(() => props.scope, load, { immediate: true });
function pointerDown(e: PointerEvent) { dragged = false; start = { x: e.clientX, y: e.clientY, pan: [...pan.value], moved: false }; }
function pointerMove(e: PointerEvent) { if (!start || !e.buttons) { start = null; return; } const rect = (e.currentTarget as Element).getBoundingClientRect(), x = (e.clientX - start.x) * 800 / rect.width, y = (e.clientY - start.y) * 560 / rect.height; start.moved ||= Math.abs(x) + Math.abs(y) > 5; if (start.moved) { dragged = true; (e.currentTarget as Element).setPointerCapture(e.pointerId); } pan.value = [start.pan[0]! + x, start.pan[1]! + y]; }
function reset() { zoom.value = 1; pan.value = [0, 0]; }
</script>
<template><div class="atlas-canvas"><svg v-if="data" viewBox="0 0 800 560" role="group" aria-label="足迹地区地图" @pointerdown="pointerDown" @pointermove="pointerMove" @pointerup="start = null" @pointercancel="start = null"><defs><pattern id="atlas-grid" width="56" height="56" patternUnits="userSpaceOnUse"><path d="M56 0H0V56" fill="none" stroke="#b7cbbd" stroke-width=".4" opacity=".4"/></pattern></defs><rect width="800" height="560" fill="url(#atlas-grid)"/><path v-for="(f,index) in paths" :key="f.code + ':' + index" class="map-region" :class="{ visited: lit(f.code) }" :d="f.path" :fill-rule="'evenodd'" :role="f.code ? 'button' : undefined" :tabindex="f.code ? 0 : undefined" :aria-label="f.name + (lit(f.code) ? '，已有足迹' : '，查看地区')" @click="region(f.code)" @keydown.enter.prevent="region(f.code, true)" @keydown.space.prevent="region(f.code, true)"/><g v-for="pin in pins" :key="pin.place.key" class="pin" :class="{ wish: pin.records === 0 }" role="button" tabindex="0" :aria-label="pin.place.name + (pin.records ? '，已到访' : '，想去')" :transform="`translate(${pin.point[0]},${pin.point[1]})`" @click.stop="pick(pin.place.key)" @keydown.enter.prevent="pick(pin.place.key, true)" @keydown.space.prevent="pick(pin.place.key, true)"><circle v-if="selected === pin.place.key" class="pin-halo" r="20"/><rect class="hit"  :x="pin.left ? -pin.labelWidth - 20 : -22" y="-24" :width="Math.max(60, pin.labelWidth + 42)" height="48" rx="12"/><circle class="pin-core" r="5"/><text class="pin-label" :x="pin.left ? -12 : 12" :text-anchor="pin.left ? 'end' : 'start'" y="5">{{ pin.label }}</text></g></svg><div v-if="loading || error" class="atlas-map-status"><p :role="error ? 'alert' : 'status'">{{ error || '正在展开足迹地图…' }}</p><button v-if="error" class="text-button" @click="load">重新加载底图</button></div><div class="atlas-map-tools"><button class="icon-button" aria-label="放大足迹地图" :disabled="zoom >= 4" @click="zoom = Math.min(4, zoom + .5)"><AtlasIcon name="plus"/></button><button class="icon-button" aria-label="缩小足迹地图" :disabled="zoom <= 1" @click="zoom = Math.max(1, zoom - .5)"><AtlasIcon name="minus"/></button><button class="icon-button" aria-label="重置足迹地图" @click="reset"><AtlasIcon name="locate"/></button></div><p v-if="data" class="atlas-source"><a :href="data.sourceUrl" target="_blank" rel="noreferrer">{{ data.attribution }}</a> · 城市代表点，非导航</p></div></template>
